SET WRITE_DELAY 0;
CREATE TABLE IF NOT EXISTS app_lock (id INT PRIMARY KEY);
MERGE INTO app_lock KEY(id) VALUES(1);
CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(200) NOT NULL CHECK(LENGTH(TRIM(name))>0));
CREATE TABLE IF NOT EXISTS recycling_types (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(200) NOT NULL, unit VARCHAR(30) NOT NULL, pointsPerKg DECIMAL(19,4) NOT NULL CHECK(pointsPerKg>=0));
CREATE TABLE IF NOT EXISTS collection_points (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, address VARCHAR(300) NOT NULL, available BOOLEAN NOT NULL, dailyMassLimit DECIMAL(19,4) NOT NULL CHECK(dailyMassLimit>0));
CREATE TABLE IF NOT EXISTS point_types (pointId BIGINT REFERENCES collection_points(id) ON DELETE CASCADE, typeId BIGINT REFERENCES recycling_types(id) ON DELETE CASCADE, PRIMARY KEY(pointId,typeId));
CREATE TABLE IF NOT EXISTS recycling_batches (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, userId BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, pointId BIGINT NOT NULL REFERENCES collection_points(id) ON DELETE CASCADE, typeId BIGINT NOT NULL REFERENCES recycling_types(id) ON DELETE CASCADE, mass DECIMAL(19,4) NOT NULL CHECK(mass>0), receivedAt TIMESTAMP WITH TIME ZONE NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('ACCEPTED','CANCELLED')));
CREATE TABLE IF NOT EXISTS bonus_entries (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, batchId BIGINT NOT NULL UNIQUE REFERENCES recycling_batches(id) ON DELETE CASCADE, points DECIMAL(19,4) NOT NULL CHECK(points>=0), status VARCHAR(20) NOT NULL CHECK(status IN ('PENDING','CREDITED','CANCELLED')));
CREATE TABLE IF NOT EXISTS seed_marker (id INT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS accounts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, userId BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, login VARCHAR(40) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, role VARCHAR(10) NOT NULL CHECK(role IN ('USER','ADMIN')), enabled BOOLEAN NOT NULL);
